// Correct test fixtures are consolidated here so each problem uses original, fixed examples.
const prefixProblem = PROBLEMS.find(p => p.id===14);
if (prefixProblem) prefixProblem.tests[1].expected = '';
export const BY_PATTERN = Object.fromEntries(PATTERNS.map(p => [p.id,PROBLEMS.filter(q=>q.pattern===p.id)]));
export const getProblem = id => PROBLEMS.find(p => p.id === Number(id));
export const getPattern = id => PATTERNS.find(p => p.id === id);
export const leetcodeUrl = p => `https://leetcode.com/problems/${p.title.replace(/\s*\([^)]*\)/g,'').replace(/[^a-zA-Z0-9 ]/g,'').trim().toLowerCase().replace(/\s+/g,'-')}/`;
